[P]Those who count the Force as their ally can use the Force to imbue their allies in turn. They can rest their hand on a friend''s shoulder or arm, or even just stand beside an ally as a solid, reassuring presence. As they reach out to touch the Force, they channel the power given to them through their bodies and out again, flowing into the nearby ally. Imbued allies may accomplish great and terrible feats, jumping higher, thinking faster, and striking harder with the Force. An ally need not even be able to touch the Force normally, for the Force flows through all living things.', 2, '[{"book":"reSpecialized"}]'::jsonb, '{"rows":[{"index":0,"costs":[10,0,0,0],"spans":[4,0,0,0],"abilities":["IMBUEBPRE","IMBUEBPRE","IMBUEBPRE","IMBUEBPRE"],"directions":[{"up":false,"down":true,"left":false,"right":false},{"up":false,"down":true,"left":false,"right":false},{"up":false,"down":false,"left":false,"right":false},{"up":false,"down":true,"left":false,"right":false}]},{"index":1,"costs":[5,10,10,10],"spans":[1,1,1,1],"abilities":["IMBRANGE","IMBSTRENGTH","PROWEAK","IMBMAGNITUDE"],"directions":[{"up":true,"down":true,"left":false,"right":false},{"up":true,"down":true,"left":false,"right":false},{"up":false,"down":true,"left":false,"right":false},{"up":true,"down":true,"left":false,"right":false}]},{"index":2,"costs":[15,10,0,10],"spans":[1,2,0,1],"abilities":["IMBRANGEIMP","TRANSFERENCE","TRANSFERENCE","IMBDURATION"],"directions":[{"up":true,"down":true,"left":false,"right":false},{"up":true,"down":true,"left":false,"right":true},{"up":true,"down":true,"left":true,"right":true},{"up":true,"down":true,"left":true,"right":false}]},{"index":3,"costs":[15,0,10,0],"spans":[2,0,2,0],"abilities":["GUIDEBEREFT","GUIDEBEREFT","IMBSPEED","IMBSPEED"],"directions":[{"up":true,"down":true,"left":false,"right":true},{"up":true,"down":false,"left":true,"right":true},{"up":true,"down":false,"left":true,"right":false},{"up":true,"down":true,"left":false,"right":false}]},{"index":4,"costs":[10