INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('TRANSFERENCE', 'Transference', 'The user may spend [FP] to activate both Imbue and Exhaust as a single Power check, choosing different targets within range for each. The same characteristic must be chosen for each target, and the target(s) of Imbue and the user gain 1 conflict.', 'IMBUERE', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
