INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTRANGEIMP', 'Range (Improved)', 'When the user activates the Range upgrade, increase the range by 2 range bands instead of 1.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTSPEED', 'Speed', 'Once per encounter, the user may suffer 3 strain to perform Insight as a maneuver. If they do, they may not activate Insight again this round.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTMAGIMP', 'Magnitude (Improved)', 'Once per round when activating Magnitude, may spend  [FP][FP] to affect additional allies or foes equal to the user''s Force rating instead.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTMASTERY', 'Mastery', 'Once per session after successfully activating the Basic power, the user may spend [FP][FP][FP] to specify the next action one NPC target will take, adding the user''s choice of [SU] or [FA] to any check that character makes until the user''s next turn. Per GM discretion, action should be within the target''s normal characterization and not be obviously suicidal.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('STEPAHEAD', 'A Step Ahead', 'The user adds [BO][BO] to all checks they make against the target until the end of the next round.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('BACKFOOT', 'On The Back Foot', 'Add [SE][SE] to all checks the target makes against the user until the end of the next round.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTRANGE', 'Range', 'The user may spend [FP] to increase the range of the Basic power and Shared Initiative by 1 range band. The user may activate this multiple times.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTSTRENGTH', 'Strength', 'Spend [FP][FP] to add [SU][AD] to each check affected by Empowered Initiative. Additionally, the user may spend [FP][FP] to increase the number of dice added by A Step Ahead and On The Back Foot by one, and may do so multiple times.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTDURATION', 'Duration', 'Spend [FP] to extend the effects of Insight for an additional round. The user may activate this multiple times.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTMAGNITUDE', 'Magnitude', 'The user may spend [FP] to affect an additional ally with Shared Initiative or character with the Basic power. The user may activate this multiple times.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SHAREDINIT', 'Shared Initiative', 'When using Insight while making an initiative check, an ally within range adds the same symbols to checks they make during the first round of the encounter.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('SEIZEMOMENT', 'Seize the Moment', 'When performing an Insight power check as part of an initiative check, if no [DA] were spent, each ally adds [SU] to their initiative check. If [DA] was used, the user may take an action before the encounter begins, but each foe adds [SU] to their initiative check.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('INSIGHTBPRE', 'Insight Basic Power (Respec)', 'The user may spend a [FP] to gain hints about what an individual within short range is likely to do in the near future. In structured gameplay, this knowledge does not typically extend beyond the end of the current encounter.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
INSERT INTO ref_force_abilities (key, name, description, power_key, dataset_source, is_retired, pip_cost, sources) VALUES ('EMPOWEREDINIT', 'Empowered Initiative', 'When making a check to determine initiative, the user may make an Insight Power check as a part of the pool. Spend [FP] to add [SU] and/or [AD] to all checks the user makes during the first round of the encounter, but only one of each symbol.', 'INSIGHTRESPEC', 'respec', false, 1, NULL) ON CONFLICT (key, dataset_source) DO NOTHING;
